if(story&&storyVideo){const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');let frame=0;const syncStory=()=>{frame=0;const range=Math.max(1,story.offsetHeight-innerHeight),progress=Math.min(1,Math.max(0,-story.getBoundingClientRect().top/range));if(!reduceMotion.matches&&storyVideo.readyState>=2&&Number.isFinite(storyVideo.duration)&&storyVideo.duration>0)storyVideo.currentTime=progress*storyVideo.duration;if(storyProgress)storyProgress.style.transform=`scaleX(${progress})`;const active=Math.min(storySteps.length-1,Math.floor(progress*storySteps.length));storySteps.forEach((step,index)=>step.classList.toggle('is-active',index===active))};const requestSync=()=>{if(!frame)frame=requestAnimationFrame(syncStory)};['loadedmetadata','loadeddata','canplay','canplaythrough'].forEach(event=>storyVideo.addEventListener(event,requestSync));window.addEventListener('scroll',requestSync,{passive:true});window.addEventListener('resize',requestSync);reduceMotion.addEventListener?.('change',requestSync);syncStory()}
const dialog=document.getElementById('lightbox');let currentPhoto=0;let previousFocus=null;
const activePhotos=()=>{const real=[...document.querySelectorAll('.chale4-real-gallery img,.chale2-real-gallery img')];return real.length?real.map(img=>({src:img.src,alt:img.alt})):route&&document.body.dataset.detail?route.gallery.map((src,index)=>({src,alt:`${route.name} — ${route.features[index]||'detalhe da acomodação'}`})):photos};
function renderPhoto(){const list=activePhotos();const p=list[currentPhoto];const img=document.getElementById('lightbox-image');if(!img||!p)return;img.src=p.src.includes('/')?p.src:`/assets/${p.src}.jpg`;img.alt=p.alt;document.getElementById('lightbox-caption').textContent=p.alt;document.getElementById('lightbox-count').textContent=`${currentPhoto+1} / ${list.length}`}
function stepPhoto(delta){const list=activePhotos();currentPhoto=(currentPhoto+delta+list.length)%list.length;renderPhoto()}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{if(!dialog)return;previousFocus=button;currentPhoto=Number(button.dataset.gallery);renderPhoto();dialog.showModal();document.getElementById('lightbox-close').focus()}));
document.getElementById('lightbox-close')?.addEventListener('click',()=>dialog.close());document.getElementById('lightbox-prev')?.addEventListener('click',()=>stepPhoto(-1));document.getElementById('lightbox-next')?.addEventListener('click',()=>stepPhoto(1));
dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepPhoto(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepPhoto(1)}});dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog?.addEventListener('close',()=>previousFocus?.focus());
